   {
    "id": "FAM:SF-CHT-025",
    "status_as_recorded": "artifact",
    "finding": "Play-type labelling audit found OTHER PPP inflated by foul-ending possessions (36% of OTHER end in fouls), DRIVE 12pp below the foul benchmark, and initiation_type mapping only 335 of 50,668 possessions (0.7%) to a real play type. Verdict recorded as artifact_found."
   },
   {
    "id": "FAM:SF-APPM-014",
    "status_as_recorded": "not a hypothesis test",
    "finding": "Play-type label accuracy audit failed overall: OTHER 20.2% against a <10% target, 40.8% low confidence, DRIVE foul-draw 1.7% against a 14-22% benchmark, most PT PPP above benchmark, and identity checks failed. Verdict recorded as tool_eval_fail."
   },
   {
    "id": "FAM:SF-CHT-029",
    "status_as_recorded": "artifact",
    "finding": "Cross-possession decay gate failed: DRIVE lifts were flat across lags (+0.015 to +0.021), within-team lag-1 effect ranged from +0.015 to -0.002, effect sizes were about d 0.01-0.03 with p near 0 from n>150k, and a team-quality confound was recorded. Verdict failed_gate."
   },
   {
    "id": "FAM:SF-CHT-052",
    "status_as_recorded": "inconclusive",
    "finding": "Similarity of replacement play-type profiles did not separate absorption from cascade (ABSORBED +0.863 vs CASCADE +0.848; Spearman -0.19, wrong-signed). Observational sample and power were not recorded."
   },
   {
    "id": "FAM:SF-APPS-010",
    "status_as_recorded": "inconclusive",
    "finding": "DRIVE PPP rose across playoff series buckets (0.889 to 0.949, +0.060), with no clear signal. Pooled 1197 records, no CIs, observational with selection caveats; mechanism recorded as unclear."
   },
   {
    "id": "FAM:SF-CHT-028",
    "status_as_recorded": "untestable",
    "finding": "Pattern-module stability was unstable (stability CV 0.919) across 23 games and 46 team-observations, with tautological keys and about 6.9 observations per key. Recommended merging into possession_flow."
   },
   {
    "id": "FAM:SF-APPS-049",
    "status_as_recorded": "rejected",
    "finding": "Across 52 series (104 playoff team-offense units), no conditional pivot branch met the durability bar (durable_branches empty). Median net swing was CUT +0.36, DRIVE -0.27, POST_UP -0.22. The record's unit listing was truncated in the retrieved text."
   },
   {
    "id": "FAM:SF-APPA-066",
    "status_as_recorded": "not a hypothesis test",
    "finding": "TOV_FORCE matchup decomposition on four playoff games: team-PT lifts were small, while player-channel lifts were large on small n (cell n about 15-54). No holdout or game-outcome check."
   },
   {
    "id": "FAM:SF-APPM-054",
    "status_as_recorded": "rejected",
    "finding": "Playoff adaptation-pair sustainability across 74 matchups (pair n 5 to 44): 10 of 12 pairs were within 0.10 of non-pivot, and two pairs with enough signal were PIVOT_LOSES. Recorded as B_powered_null with small-sample limitation."
   }
  ],
  "failed_approaches": [
   {
    "id": "FAM:SF-CHT-025",
    "what_failed": "Deriving play-type class from initiation_type mapping and comparing play-type PPP",
    "why": "Recorded as artifact: foul-ending possessions leaked into OTHER and DRIVE; initiation_type mapped only 0.7% of possessions to a real play type."
   },
   {
    "id": "FAM:SF-APPM-014",
    "what_failed": "Play-type label accuracy and distribution audit",
    "why": "Recorded as tool_eval_fail: OTHER share was 20.2% against a target under 10%, 40.8% of labels were low confidence, DRIVE foul-draw was off benchmark, and identity checks failed."
   },
   {
    "id": "FAM:SF-CHT-029",
    "what_failed": "Cross-possession decay (lag) test of play-type memory",
    "why": "Recorded as failed_gate: lifts were flat rather than decaying, collapsed under a within-team baseline, and carried a team-quality confound (LIM:confounding)."
   },
   {
    "id": "FAM:SF-CHT-052",
    "what_failed": "Using play-type profile similarity to separate absorption from cascade",
    "why": "Recorded as inconclusive with a wrong-signed correlation and a label-error limitation; sample and power were not recorded."
   },
   {
    "id": "FAM:SF-APPS-010",
    "what_failed": "Tracking play-type PPP across playoff series game buckets",
    "why": "Recorded as E_unclear: no clear signal, observational data with selection and regression-to-the-mean caveats, and no CIs."
   },
   {
    "id": "FAM:SF-CHT-028",
    "what_failed": "Stability of a pattern-module (action_sequences) signal",
    "why": "Recorded as A_unanswerable: stability CV 0.919, tautological keys, and about 6.9 observations per key across 23 games."
   },
   {
    "id": "FAM:SF-APPA-066",
    "what_failed": "Player-channel matchup decomposition on four playoff games",
    "why": "Recorded as A_unanswerable with EXPOSURE_SPARSITY: player-channel cells of about 15-28 defensive possessions and helper-steal attribution noise."
   },
   {
    "id": "FAM:SF-APPM-054",
    "what_failed": "Sustained PPP after pivoting to a listed counter in playoff matchups",
    "why": "Recorded as B_powered_null with small sample (pair n 5 to 44); two pairs showed PIVOT_LOSES, and population deltas were mostly under 0.10."
   }
  ],
  "evidence_establishes": [
   "Play-type labels derived from this pipeline have documented accuracy problems: foul leakage into OTHER and DRIVE, low initiation_type coverage, and failed identity checks (FAM:SF-CHT-025, FAM:SF-APPM-014).",
   "DRIVE-associated PPP fell sharply from regular season to playoffs in one team-level comparison (FAM:SF-APPS-011, supported, no CIs).",
   "Earlier attempts to test play-type memory, pivots, and replacement similarity in this project did not yield a robust, powered positive result (FAM:SF-CHT-029, FAM:SF-APPM-054, FAM:SF-CHT-052, FAM:SF-APPS-049).",
   "No retrieved record tests whether cut-heavy shaper roles transfer better than drive-heavy roles."
  ],
  "evidence_does_not_establish": [
   "Whether cut-heavy shaper roles transfer better than drive-heavy roles. No retrieved record defines or tests shaper classes or a transfer metric.",
   "Whether DRIVE's regular-season-to-playoff PPP drop reflects role transfer, labelling error, or team-quality composition, since the supporting record has no CIs and its labels are contested by the audits.",
   "Any estimate at n=24 units. No retrieved record reports a power analysis for a 24-unit comparison.",
   "Whether the 2022-23 to 2025-26 data version in the current pipeline has the same labelling defects as the retrieved studies, which may have used other data versions."
  ],
  "own_inferences": [
   "The question's key term 'travel' is undefined. Without an operational transfer metric, no test can be pre-registered.",
   "With 24 units, detecting a moderate class difference in transfer would need a very large effect or many repeated units per shaper, which the data does not provide.",
   "Cut-heavy versus drive-heavy classes are likely confounded with team quality, role, usage, and position, and the retrieved records show team-quality confounding is already a documented failure mode (FAM:SF-CHT-029).",
   "The strongest retrieved signal (FAM:SF-APPS-011) is about DRIVE PPP falling into the playoffs, which is related to the question but not the same estimand. It is also weakened by the labelling failures in FAM:SF-CHT-025 and FAM:SF-APPM-014."
  ],
  "uncertainties": [
   "The retrieved records do not state whether the current data version (2022-23 to 2025-26, with partial 2025-26 playoffs before 2026-06-21) is the same one used in earlier studies.",
   "The text of FAM:SF-APPS-049 and FAM:SF-APPA-066 was truncated in the retrieved results, so their full unit lists and any further results are unknown. Read_family was not called.",
   "No CIs were recorded in several supporting records, so effect magnitudes are uncertain.",
   "Whether 'cut-heavy' and 'drive-heavy' shapers can be classified reliably from the derived records is untested."
  ],
  "historical_effect": {
   "changed_decision": "yes",
   "explanation": "The retrieved records show repeated labelling failures (FAM:SF-CHT-025, FAM:SF-APPM-014), a team-quality confound (FAM:SF-CHT-029), and several underpowered or unstable tests (FAM:SF-CHT-028, FAM:SF-APPA-066, FAM:SF-APPM-054). Together they move the decision from a standard test to do_not_proceed as posed. A minimum viable test is specified below, contingent on label validation."
  }
 },
 "testability": {
  "p_testable": 0.1,
  "blocking_constraints": [
   {
    "code": "MEASURE_RELIABILITY",
    "text": "Shaper classes and the transfer metric are undefined. The retrieved play-type labels have documented accuracy failures (FAM:SF-APPM-014, FAM:SF-CHT-025)."
   },
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "n=24 units is too small to detect a moderate class difference in transfer, given that prior powered tests here returned nulls or underpowered results (FAM:SF-APPM-054, FAM:SF-APPS-049)."
   },
   {
    "code": "CONFOUNDING",
    "text": "Shaper class is likely confounded with team quality, usage, position, and context, which was the failure mode for FAM:SF-CHT-029."
   },
   {
    "code": "LABEL_ERROR",
    "text": "Play-type labels have foul leakage and low initiation_type coverage (0.7%), so the class definition itself is unreliable (FAM:SF-CHT-025)."
