 },
 "prior_work": {
  "already_answered": "no",
  "cited": [
   "FAM:SF-APPS-011",
   "FAM:SF-CHT-025",
   "FAM:SF-APPM-014",
   "FAM:SF-CHT-029",
   "FAM:SF-APPS-049",
   "FAM:SF-APPM-054"
  ],
  "summary": "No retrieved record tests whether cut-heavy shaper roles transfer better than drive-heavy roles. The nearest records concern play-type labels (failed audits), DRIVE PPP falling from regular season to playoffs (one supported, unadjusted team-level result), and attempts to test memory, pivots, and sustainability (mostly null, underpowered, or unstable). These inform the design risks but do not answer the question."
  },
 "risks": [
  {
   "code": "MEASURE_RELIABILITY",
   "text": "Transfer metric and shaper class are undefined; label accuracy is unvalidated (FAM:SF-APPM-014, FAM:SF-CHT-025)."
  },
  {
   "code": "LABEL_ERROR",
   "text": "Foul possessions leak into OTHER and DRIVE; initiation_type coverage is 0.7%; identity checks failed."
  },
  {
   "code": "OUTCOME_DERIVED_LABEL",
   "text": "Play-type classes are built from points and possession outcomes; any transfer metric based on PPP would circularly depend on the same outcome."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "n=24 units; retrieved powered tests returned nulls or small-sample results (FAM:SF-APPM-054, FAM:SF-APPS-049)."
  },
  {
   "code": "CONFOUNDING",
   "text": "Team quality, usage, position, and playoff context are likely confounders, as recorded in FAM:SF-CHT-029 and FAM:SF-APPS-011 (no adjustment or CIs)."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "Small per-unit possession counts (about 15-54 in FAM:SF-APPA-066) and minimum-30 cell rules in FAM:SF-APPS-011 limit precision."
  },
  {
   "code": "MULTIPLE_TESTING",
   "text": "Many play types, contexts (RS, playoffs, series buckets), and lags invite multiple comparisons, as in FAM:SF-APPS-010 and FAM:SF-APPS-011."
  },
  {
   "code": "PLACEBO_DEPENDENCE",
   "text": "No placebo or negative-control play type or season was recorded in the retrieved records; any transfer effect could reflect baseline differences."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "Pattern stability was poor (FAM:SF-CHT-028, CV 0.919), and the 2025-26 playoff data are partial before 2026-06-21."
  },
  {
   "code": "IMPLEMENTATION_BUG",
   "text": "Derived play-type records are built in a graph database from play-by-play; mapping errors (such as initiation_type) are not verified."
  }
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.1,
  "untestable": 0.5,
  "artifact": 0.2,
  "uncertain": 0.15
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "Difference in a pre-specified role-transfer metric (for example, change in the shaper's own offensive role profile or PPP across a context shift) between cut-heavy and drive-heavy shapers. The metric must be defined before analysis, and this is not yet available.",
  "unit": "Player-season (or player-context) shaper, not team-PT cell, to avoid the single-team labelling noise seen in prior work.",
  "sample": "Current n=24 units is insufficient. A viable test needs the full set of shapers across the four regular seasons and playoffs, with the transfer metric defined first. Sample size must be fixed by a power calculation.",
  "power": "Not achievable at n=24 for a moderate effect. Compute the minimum detectable effect from the full player-context sample before proceeding; if MDE is larger than plausible effects, the test is not worth running.",
  "controls": "Adjust for team quality (team net rating or prior-season team PPP), usage rate, position, minutes, and playoff-round/series game number. Use within-team comparisons where possible, as in FAM:SF-CHT-029.",
  "falsification": "Negative-control shaper classes (for example, POST_UP-heavy or PULL_UP-heavy) and a placebo transfer context (regular season split in half) should show no difference. A difference in placebo contexts disqualifies the result.",
  "multiplicity": "Pre-register one primary contrast (cut-heavy minus drive-heavy transfer metric). Treat other play types and contexts as exploratory with Holm correction.",
  "decision_rule": "Proceed only if (a) play-type labels pass a pre-specified validation audit (OTHER share under the target, foul-draw rates within benchmark, initiation_type coverage above a set threshold, and identity checks passed), and (b) the power analysis shows MDE below a pre-specified practically meaningful effect. Otherwise report the question as untestable with the current data.",
  "data_version": "NBA 2022-23 to 2024-25 regular seasons and playoffs, plus 2025-26 regular season complete from 2026-04-13. Exclude the 2025-26 playoffs until complete (from 2026-06-21). Record the exact data pull date and label-pipeline version."
 }
 }
}

